def main():
    n, m = map(int, input().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b = map(int, input().split()); adj[a].append(b)
    seen = {1}; st = [1]
    while st:
        u = st.pop()
        for v in adj[u]:
            if v not in seen: seen.add(v); st.append(v)
    print(len(seen))

def main():
    n, m, k = map(int, input().split())
    M = 10**9 + 7
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b = map(int, input().split()); adj[a].append(b)
    v = [0] * (n + 1); v[1] = 1
    for _ in range(k):
        w = [0] * (n + 1)
        for u in range(1, n + 1):
            for x in adj[u]: w[x] = (w[x] + v[u]) % M
        v = w
    print(sum(v) % M)

